INSERT INTO `posts` (`id`, `user_id`, `title`, `slug`, `category`, `excerpt`, `content`, `thumbnail`, `status`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1, 'Selamat Bapak Bupati Majalengka', 'selamat-bapak-bupati-majalengka', 'Penghargaan', 'Keluarga besar Dinas Pariwisata dan Kebudayaan Kabupaten Majalengka mengucapkan selamat kepada Bapak Eman Suherman, Bupati Majalengka, atas diraihnya penghargaan Kepala Daerah Inspiratif dalam Penguatan Keagamaan dan Kebersamaan Umat pada ajang Kabar Cirebon Awards 2026.\r\n\r\nPenghargaan ini menjadi apresiasi atas komitmen dalam memperkuat nilai-nilai keagamaan, kebersamaan, serta harmoni di tengah masyarakat.', '<p>Keluarga besar Dinas Pariwisata dan Kebudayaan Kabupaten Majalengka mengucapkan selamat kepada Bapak Eman Suherman, Bupati Majalengka, atas diraihnya penghargaan Kepala Daerah Inspiratif dalam Penguatan Keagamaan dan Kebersamaan Umat pada ajang Kabar Cirebon Awards 2026.</p>\r\n\r\n<p><br></p>\r\n\r\n<p>Penghargaan ini menjadi apresiasi atas komitmen dalam memperkuat nilai-nilai keagamaan, kebersamaan, serta harmoni di tengah masyarakat.</p>\r\n\r\n<p><br></p>\r\n\r\n<p>Semoga penghargaan ini menjadi motivasi untuk terus menghadirkan Majalengka yang religius, harmonis, dan penuh kebersamaan.</p>\r\n\r\n<p><br></p>\r\n\r\n<p>Selamat dan terus menginspirasi, untuk Majalengka Langkung Sae!</p>', 'posts/76XZBuZoU50WhcVemiz0aGEKTBAhOrfqT2lst7cL.png', 'published', '2026-10-04 14:43:00', NULL, NULL, '2026-10-04 07:43:54', '2026-10-04 07:43:54', NULL);
